{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "Cabozantinib, the closest structural analogue with a diaryl ether kinase-inhibitor scaffold, showed negligible brain uptake in mice by biodistribution and µPET imaging, demonstrating that this chemotype can be effectively excluded from the CNS despite activity in brain tumors.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "MLN2480, which shares the chloro-CF3-phenyl and heteroaromatic amide features, had brain delivery restricted by P-gp and/or Bcrp efflux in vivo, directly supporting efflux-limited CNS access for the query chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "A related chloro-CF3-phenyl heteroaryl compound had a Kp,uu of 0.025 in mouse, indicating very low unbound brain-to-plasma exposure and poor meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "A more distantly related heteroaryl amide achieved a rat brain:plasma Kp of 1.68, showing that not all analogues in this broad chemical space are poor CNS penetrants; however, this does not override the closer efflux-positive and low-brain-uptake analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is sorafenib, a diaryl-ether urea with high lipophilicity and a known P-gp/BCRP efflux liability. The closest experimental analogues with direct CNS measurements show negligible or efflux-limited brain uptake, and the physicochemical prior is unfavorable; therefore meaningful CNS access after systemic administration is unlikely.",
  "evidence_gaps": [
    "No direct sorafenib brain, CSF, or unbound brain concentration measurement was included in the evidence set.",
    "All evidence analogues have modest Morgan similarity (<0.30), limiting direct transferability.",
    "Several 'permeable' analogues were labeled based on total brain:plasma ratios below 1, which do not establish meaningful free brain exposure."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "moderate",
      "card_ids": ["C07"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "diaryl ether kinase inhibitor CNS exposure"
    }
  ],
  "revision_action": "initial"
}

